import sys, random, copy, json, math, traceback, time
sys.path.insert(0,'submission')
from protocol import validate
from te.session import run_case
from tmp.verify_replay import verify_request

def gen_simple_paths(n, adj, s, t, maxlen=12, maxpaths=30):
    out=[]
    def dfs(u,path,seen):
        if len(out)>=maxpaths: return
        if u==t:
            if path: out.append(list(path))
            return
        if len(path)>=maxlen: return
        for v,e in adj.get(u,[]):
            if v not in seen:
                seen.add(v);path.append(e);dfs(v,path,seen);path.pop();seen.remove(v)
                if len(out)>=maxpaths: return
    dfs(s,[],{s})
    return out

def gen_case(caseidx, scenario=0):
    n=random.randint(2,10)
    # unique ordered directed edges: chain plus random extras
    edge_pairs=[]
    used=set()
    for i in range(n-1):
        used.add((i,i+1));edge_pairs.append((i,i+1))
    cand=[(u,v) for u in range(n) for v in range(n) if u!=v and (u,v) not in used]
    random.shuffle(cand)
    for p in cand[:random.randint(0,min(50,len(cand)))]:
        used.add(p);edge_pairs.append(p)
    random.shuffle(edge_pairs)
    E=len(edge_pairs)
    if E>64: edge_pairs=edge_pairs[:64];E=64
    caps=[random.choice([0,1,1,2,3,5,10,50,1000]) for _ in range(E)]
    edges=[[u,v,caps[i]] for i,(u,v) in enumerate(edge_pairs)]
    # adjacency with edge ids
    adj={u:[] for u in range(n)}
    for e,(u,v) in enumerate(edge_pairs): adj[u].append((v,e))
    K=random.randint(0,8)
    coms=[]; allpaths=[]
    slot_total=0
    for k in range(K):
        # choose distinct source/sink, mostly chain-connected
        for _ in range(20):
            s=random.randrange(n);t=random.randrange(n)
            if s!=t: break
        poss=gen_simple_paths(n,adj,s,t,12,60)
        random.shuffle(poss)
        maxslots=min(8,len(poss),96-slot_total)
        T=random.randint(0,max(0,maxslots))
        group=[]
        for j in range(T):
            if poss and random.random()<0.85:
                group.append(list(poss.pop()))
            else:
                group.append(None)
        # Ensure nonnull distinct: poss sampled unique, nulls okay
        slot_total+=len(group)
        coms.append({'source':s,'sink':t,'demand':random.choice([0,0,1,2,5,10,100,1000]),'paths':group})
        allpaths.append(poss)  # remaining possible for configure
    W=random.randint(1,min(5,max(1,K+2)))
    assignments=[[] for _ in range(W)]
    for k in range(K): assignments[random.randrange(W)].append(k)
    workers=[sorted(a) for a in assignments]
    quorum=random.randint(1,W)
    maxlag=random.randint(0,12)
    while True:
        b=random.randint(1,16);a=random.randint(b,min(16,2*b-1))
        break
    mode=random.choice(['route','admit'])
    events=[]
    issued=[]
    saves=[]
    ticket_pool=list(range(0,100))
    random.shuffle(ticket_pool)
    name_pool=list(range(1000,1100));random.shuffle(name_pool)
    n_issue=random.randint(0,min(10,48))
    n_events=random.randint(1,30)
    next_issue=0
    for i in range(n_events):
        choices=['step','audit','retune','issue','deliver','save','restore','configure']
        if scenario==1 and i<W:
            choices=['issue']
        elif scenario==1 and i<W+W:
            choices=['deliver']
        elif scenario==1 and i<W+W+3:
            choices=['step']
        elif scenario==1:
            choices=['audit','retune','configure','save','restore','step']
        op=random.choice(choices)
        if op=='issue' and next_issue>=n_issue: op='audit'
        if op=='deliver' and not issued: op='audit'
        if op=='restore' and not saves: op='audit'
        if op=='configure':
            capchg=[]
            ids=list(range(E));random.shuffle(ids)
            for e in ids[:random.randint(0,min(5,E))]:
                capchg.append([e,random.choice([0,1,2,5,10,1000])])
            demchg=[]
            ids=list(range(K));random.shuffle(ids)
            for k in ids[:random.randint(0,min(3,K))]:
                demchg.append([k,random.choice([0,1,5,100,1000])])
            pathchg=[]
            # Replace all slots of up to two commodities with a distinct valid group.
            for k in random.sample(range(K),random.randint(0,min(2,K))):
                T=len(coms[k]['paths'])
                candidates=allpaths[k][:]
                random.shuffle(candidates)
                newg=[]
                for j in range(T):
                    if candidates and random.random()<0.8:
                        newg.append(list(candidates.pop()))
                    else:
                        newg.append(None)
                for j in range(T): pathchg.append([k,j,newg[j]])
            events.append({'op':'configure','mode':random.choice(['route','admit']),
                           'capacity':capchg,'demand':demchg,'paths':pathchg})
        elif op=='issue':
            tid=ticket_pool[next_issue];next_issue+=1
            ev={'op':'issue','id':tid,'worker':random.randrange(W)}
            events.append(ev);issued.append(tid)
        elif op=='deliver':
            events.append({'op':'deliver','id':random.choice(issued)})
        elif op=='step': events.append({'op':'step'})
        elif op=='audit': events.append({'op':'audit'})
        elif op=='retune': events.append({'op':'retune','rho':random.randint(1,8)})
        elif op=='save':
            name=name_pool.pop();saves.append(name);events.append({'op':'save','name':name})
        elif op=='restore': events.append({'op':'restore','name':random.choice(saves)})
    return {'nodes':n,'edges':edges,'commodities':coms,'workers':workers,'quorum':quorum,
            'max_lag':maxlag,'relax':[a,b],'rho':random.randint(1,8),'mode':mode,'events':events}

def main():
    random.seed(20251113)
    t0=time.time()
    for trial in range(500):
        ncases=random.choices([0,1,1,1,2,3],[1,4,5,5,2,1])[0]
        cases=[gen_case(i,trial%2) for i in range(ncases)]
        req={'cases':cases}
        try:
            validate(req)
        except Exception as e:
            print('generator validate failed',trial,e);print(json.dumps(req));raise
        out={'cases':[run_case(c) for c in cases]}
        try:
            verify_request(req,out)
        except Exception as e:
            print('VERIFY FAIL trial',trial,repr(e))
            traceback.print_exc()
            with open('tmp/fail_req.json','w') as f: json.dump(req,f)
            with open('tmp/fail_out.json','w') as f: json.dump(out,f)
            break
        if trial%25==0: print('trial',trial,'ok',time.time()-t0)
    else:
        print('ALL RANDOM REPLAY OK',time.time()-t0)
if __name__=='__main__': main()
